commit e99660fd0f31188285c541d51430087f4d34f196
Author: Nxeon <haxkodi@gmail.com>
Date:   Sat Sep 26 16:13:12 2026 +0000

    Make management-key generation best-effort during provisioning

    Found while checking this feature's blast radius: the ssh-keygen call at
    provision time was unguarded, so a hiccup there (disk pressure, a future
    environment missing ssh-keygen) would throw and fail a brand-new paying
    customer's whole order just to add a convenience feature. Wrapped in
    try/catch — a failure here now just skips the management key for that
    server (falls through to password auth exactly as before this shipped) and
    logs loudly, instead of blocking provisioning.

    Co-Authored-By: Claude Sonnet 5 <noreply@anthropic.com>

diff --git a/worker/index.ts b/worker/index.ts
index 6191dd9106..665ce09511 100644
--- a/worker/index.ts
+++ b/worker/index.ts
@@ -857,15 +857,29 @@ async function provision(job: Job) {
   // staff support keep working even if the customer later sets
   // PasswordAuthentication no. The private half is stored encrypted;
   // provisioning never has a reason to hold it in memory past this call.
-  const managementKeypair = generateManagementKeypair(`nxeon-mgmt-${server.id}`);
-  await db.server.update({
-    where: { id: server.id },
-    data: {
-      sshManagementKeyEnc: encryptSecret(managementKeypair.privateKeyOpenSsh),
-      sshManagementPublicKey: managementKeypair.publicKeyLine,
-    },
-  });
-  const allPublicKeys = [...keys.map((k) => k.publicKey.trim()), managementKeypair.publicKeyLine];
+  //
+  // BEST-EFFORT, DELIBERATELY. This is a convenience/resilience feature on top
+  // of a provision that worked fine without it for the whole life of this
+  // codebase — a `ssh-keygen` hiccup (disk pressure, a future environment that
+  // doesn't have it) must never fail a paying customer's order. A server that
+  // falls through this catch simply gets provisioned exactly like it always
+  // has (password auth only) and can be picked up later by
+  // scripts/backfill-ssh-management-keys.ts.
+  let managementPublicKey: string | undefined;
+  try {
+    const managementKeypair = generateManagementKeypair(`nxeon-mgmt-${server.id}`);
+    await db.server.update({
+      where: { id: server.id },
+      data: {
+        sshManagementKeyEnc: encryptSecret(managementKeypair.privateKeyOpenSsh),
+        sshManagementPublicKey: managementKeypair.publicKeyLine,
+      },
+    });
+    managementPublicKey = managementKeypair.publicKeyLine;
+  } catch (e) {
+    console.error(`[worker] management key generation failed for ${server.id} — continuing without one`, e);
+  }
+  const allPublicKeys = [...keys.map((k) => k.publicKey.trim()), ...(managementPublicKey ? [managementPublicKey] : [])];
   const sshkeys = encodeURIComponent(allPublicKeys.join("\n"));
   // A game order's REAL entitlement is its OWN ramMB/cpuCores/diskGB — the
   // exact numbers advertised and sold ("Project Zomboid — 6 GB / 8 players").

