149	/**
150	 * Pull additional/failover IPv4 addresses routed to a node's server from its
151	 * provider and upsert them into the pool. The host's own primary IP is never
152	 * poolable. Defaults to the primary (OVH) node when no `nodeId` is given —
153	 * identical behavior to before this file supported more than one node.
154	 */
155	export async function syncDedicatedIpPool(nodeId?: string): Promise<{ imported: number; total: number }> {
156	  if (SANDBOX) return { imported: 0, total: 0 };
157	  const node = await resolveNode(nodeId);
158	  if (!node || !node.providerServerId) return { imported: 0, total: 0 };
159	
160	  if (node.provider === "HETZNER") return syncHetznerPool(node);
161	  return syncOvhPool(node);
