164	async function syncOvhPool(node: NodeRow): Promise<{ imported: number; total: number }> {
165	  if (!ovhConfigured()) return { imported: 0, total: 0 };
166	  const SERVER = node.providerServerId!;
167	  const primary = node.publicIp;
168	  const blocks: string[] = await ovhApi.ips();
169	  let imported = 0;
170	  for (const block of blocks) {
171	    if (block.includes(":")) continue; // IPv6 handled separately
172	    let info: any;
173	    try {
174	      info = await ovhApi.ipInfo(block);
175	    } catch {
176	      continue;
177	    }
178	    if (info?.routedTo?.serviceName !== SERVER) continue;
179	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
180	    // A /32 block is a single usable IP == the block minus the mask.
181	    const address = block.split("/")[0];
182	    if (address === primary) continue;
183	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
184	    if (!existing) {
185	      // An IP that already has a Virtual MAC bound to it on OVH's side is already
186	      // in active use by SOME VM — possibly one this app never created a Server
187	      // row for (e.g. internal infrastructure provisioned directly via the OVH
188	      // API, like the cold-email relay). A genuinely free IP has no bound MAC
189	      // yet. Importing it as FREE anyway let a real customer server collide with
190	      // an unrelated VM's network identity — never assign an IP that's already
191	      // claimed at the network layer, regardless of whether our DB knows about it.
192	      if (await findVirtualMacForIp(SERVER, address)) continue;
193	      if (await hasLiveDnatRule(node, address)) continue;
194	      // Every IP this function imports is, by construction, a spare address
195	      // OVH says is routed to us and not yet claimed at the network layer — the
196	      // pool customer orders draw from. Internal-use IPs (the cold-email relay,
197	      // an owner-operated site, the shared-hosting node) are rare, hand-provisioned
198	      // one-offs marked INTERNAL by an admin after the fact; this sync has no way
199	      // to tell them apart from a genuinely free customer IP and must not try —
200	      // it always imports as CUSTOMER (the schema default, stated here for clarity).
201	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, nodeId: node.id, status: "FREE", purpose: "CUSTOMER" } });
202	      imported++;
203	    }
204	  }
205	  const total = await db.dedicatedIp.count({ where: { nodeId: node.id } });
206	  return { imported, total };
207	}
