283	/**
284	 * Claim a free IP for a server and set it up so the VM can use it — an OVH
285	 * Virtual MAC for an OVH-node IP, or nothing extra for a Hetzner-node IP
286	 * (Hetzner additional IPs route straight to the server's real MAC, no
287	 * separate MAC object to create). Returns the address + a MAC (OVH only,
288	 * empty string for Hetzner) + gateway, or null if none available.
289	 *
290	 * `nodeId` should be the server's OWN node — pass it explicitly from a
291	 * caller that already resolved it (e.g. worker/index.ts's `nodeFor(server)`);
292	 * omitted, this falls back to the primary node, identical to this file's
293	 * pre-multi-node behavior.
294	 */
295	export async function allocateDedicatedIp(
296	  serverId: string,
297	  vmid: number,
298	  nodeId?: string,
299	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
300	  if (SANDBOX) {
301	    // Hand out a synthetic dedicated IP without any provider call or pool mutation.
302	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
303	  }
304	  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
305	  // server already holds a fully-allocated dedicated IP, return it instead of
306	  // claiming a second pool IP — re-claiming would leak an IP and P2002 on the
307	  // unique DedicatedIp.serverId. An OVH row also needs a bound Virtual MAC to
308	  // count as "done"; a Hetzner row is done once ASSIGNED (no MAC step).
309	  const mine = await db.dedicatedIp.findUnique({ where: { serverId }, include: { node: true } });
310	  if (mine && mine.status === "ASSIGNED" && (mine.node.provider === "HETZNER" || mine.virtualMac)) {
311	    return { address: mine.address, virtualMac: mine.virtualMac ?? "", gateway: await gatewayFor(mine.node, mine.address) };
312	  }
313	
314	  const node = await resolveNode(nodeId);
315	  if (!node) return null;
316	  if (!(await dedicatedIpProviderConfigured(node.id))) return null;
317	
318	  // Atomically claim a FREE ip belonging to THIS node's pool. Excluding
319	  // purpose: INTERNAL here is a second, independent guard (alongside the
320	  // sync-time checks above) against ever handing an admin-marked internal IP
321	  // to a customer server.
322	  const claim = await db.$transaction(async (tx) => {
323	    const ip = await tx.dedicatedIp.findFirst({
324	      where: { status: "FREE", purpose: "CUSTOMER", nodeId: node.id },
325	      orderBy: { createdAt: "asc" },
326	    });
327	    if (!ip) return null;
328	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
329	    return ip;
330	  });
331	  if (!claim) return null;
332	
333	  try {
334	    if (node.provider === "HETZNER") {
335	      await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED" } });
336	      return { address: claim.address, virtualMac: "", gateway: await gatewayFor(node, claim.address) };
337	    }
338	    // OVH branch — unchanged mechanics, just keyed off this node's own service name.
339	    const SERVER = node.providerServerId!;
340	    let mac = await findVirtualMacForIp(SERVER, claim.address);
341	    if (!mac) {
342	      // Creation is asynchronous (returns a task) — kick it off then poll.
343	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
344	      for (let i = 0; i < 40 && !mac; i++) {
345	        await new Promise((r) => setTimeout(r, 3000));
346	        mac = await findVirtualMacForIp(SERVER, claim.address);
347	      }
348	    }
349	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
350	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
351	    return { address: claim.address, virtualMac: mac, gateway: ovhGatewayFor(node.publicIp) };
352	  } catch (e) {
353	    // Roll the claim back to FREE on failure
354	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
355	    throw e;
356	  }
357	}
