383	/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual
384	 *  MAC for an OVH-node IP; a Hetzner-node IP just gets un-assigned, no
385	 *  separate MAC object to delete). */
386	export async function releaseDedicatedIp(serverId: string): Promise<void> {
387	  if (SANDBOX) return;
388	  const ip = await db.dedicatedIp.findUnique({ where: { serverId }, include: { node: true } });
389	  if (!ip) return;
390	  if (ip.node.provider === "OVH" && ovhConfigured() && ip.virtualMac && ip.node.providerServerId) {
391	    const SERVER = ip.node.providerServerId;
392	    try {
393	      // Remove the IP from the vMAC, then delete the vMAC.
394	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
395	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
396	    } catch {
397	      /* best-effort */
398	    }
399	  }
400	  await db.dedicatedIp.update({
401	    where: { id: ip.id },
402	    data: { status: "FREE", serverId: null, virtualMac: null },
403	  });
404	  // `Server.ipAddress` is UNIQUE and separate from this pool table — every
405	  // caller used to have to remember to clear it themselves, and one (the
406	  // admin "release IP" action) didn't, which left a FREE pool row while a
407	  // live server still held that exact address in `Server.ipAddress`. The next
408	  // server to claim the pool row then failed provisioning with a P2002 on
409	  // every retry, deterministically, since the failed-provision cleanup just
410	  // re-freed the same already-stuck row. Clearing it here — for every caller,
411	  // guarded to only touch the row that still holds THIS address, since the
412	  // column also holds ordinary NAT IPs for other servers — closes that class
413	  // of bug for good instead of relying on each call site to remember.
414	  await db.server.updateMany({
415	    where: { id: serverId, ipAddress: ip.address },
416	    data: { ipAddress: null, ipv6: null },
417	  });
418	}
