  // auto-generated MAC (bridge already correct from the template)
  // untouched — exactly like the plain-NAT branch below — only the
  // IP binding actually needs to change.
  cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
